# 4-neighbor components for cells with values in {1,3,6}
from collections import deque
mask=np.isin(A,[1,3,6]); seen=set(); comps=[]
for r,c in zip(*np.where(mask)):
 if (r,c) in seen: continue
 q=[(r,c)];seen.add((r,c)); pts=[]
 while q:
  x,y=q.pop();pts.append((x,y))
  for dx,dy in ((1,0),(-1,0),(0,1),(0,-1)):
   z=(x+dx,y+dy)
   if 0<=z[0]<26 and 0<=z[1]<26 and mask[z] and z not in seen: seen.add(z);q.append(z)
 rs=[x for x,y in pts];cs=[y for x,y in pts]
 comps.append((len(pts),(min(rs),max(rs),min(cs),max(cs)),sorted(set(A[x,y] for x,y in pts))))
