import itertools, numpy as np
# dihedral transforms
orients={}
for k,x in T.items():
 ar=np.array(x); os=[]
 for rr in range(4):
  a=np.rot90(ar,rr)
  for f in (False,True):
   z=np.fliplr(a) if f else a
   if not any(np.array_equal(z,q) for q in os):os.append(z)
 orients[k]=os
best=[]; maxsc=-1
for p in itertools.permutations(T):
 for ix in itertools.product(range(8),repeat=4):
  aa=[orients[k][j] for k,j in zip(p,ix)]
  # arrangement a b / c d, score matching edges
  score=np.sum(aa[0][:,-1]==aa[1][:,0])+np.sum(aa[2][:,-1]==aa[3][:,0])+np.sum(aa[0][-1,:]==aa[2][0,:])+np.sum(aa[1][-1,:]==aa[3][0,:])
  if score>maxsc: maxsc=score;best=[(p,ix,score,aa)]
  elif score==maxsc and len(best)<5:best.append((p,ix,score,aa))
maxsc,[(x[0],x[1]) for x in best]

